using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.VTS.TipoIdentificacion{    [SwaggerSchema("Modelo de lectura de un TipoIdentificacion")]    [GraphQLDescription("Objeto que representa un TipoIdentificacion existente.")]    public class clReadTipoIdentificacion    {        [SwaggerSchema("Identificador único del TipoIdentificacion")]        [GraphQLDescription("Identificador único del TipoIdentificacion")]        public int? TipoIdentificacionID { get; set; }        [SwaggerSchema("TipoIdentificacion")]        [GraphQLDescription("TipoIdentificacion")]        public string? TipoIdentificacion { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TipoIdentificacion")]    [GraphQLDescription("Input para crear un TipoIdentificacion.")]    public class clCreateTipoIdentificacion    {        [GraphQLNonNullType] [SwaggerSchema("TipoIdentificacion")]        [GraphQLDescription("TipoIdentificacion")]        public string TipoIdentificacion { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TipoIdentificacion")]    [GraphQLDescription("Input para actualizar parcialmente un TipoIdentificacion.")]    public class clUpdateTipoIdentificacion    {        [SwaggerSchema("Identificador único del TipoIdentificacion")]        [GraphQLDescription("Identificador único del TipoIdentificacion")]        public int? TipoIdentificacionID { get; set; }        [SwaggerSchema("TipoIdentificacion")]        [GraphQLDescription("TipoIdentificacion")]        public string? TipoIdentificacion { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}